-- Hyprland config (Lua) — dark, minimal, Apple-style blur, wallpaper-driven colors
-- Colors come from ~/.config/hypr/colors.lua (regenerated by matugen on wallpaper change)

package.path = os.getenv("HOME") .. "/.config/hypr/?.lua;" .. package.path
local ok, C = pcall(require, "colors")
if not ok then C = dofile(os.getenv("HOME") .. "/.config/hypr/colors.lua") end

local terminal    = "alacritty"
local fileManager = "dolphin"
local scripts     = os.getenv("HOME") .. "/.config/hypr/scripts"

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = 1 })

-------------------
---- AUTOSTART ----
-------------------
hl.on("hyprland.start", function()
    hl.exec_cmd(scripts .. "/restore-wallpaper.sh")
    hl.exec_cmd("waybar")
    hl.exec_cmd("swaync")
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("wl-paste --type text  --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("udiskie --tray --notify")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd(scripts .. "/powermode.sh restore")
end)

-----------------
---- ENVIRON ----
-----------------
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("XCURSOR_THEME", "Adwaita")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("MOZ_ENABLE_WAYLAND", "1")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("LIBVA_DRIVER_NAME", "iHD")   -- Intel iGPU video acceleration

-----------------------
---- LOOK AND FEEL ----
-----------------------
hl.config({
    general = {
        gaps_in = 5, gaps_out = 12, border_size = 1,
        col = {
            active_border   = { colors = { C.primary, C.lime or C.tertiary }, angle = 45 },
            inactive_border = C.outline_dim,
        },
        resize_on_border = true,
        allow_tearing = false,
        layout = "dwindle",
    },
    decoration = {
        rounding = 16, rounding_power = 3,
        active_opacity = 1.0, inactive_opacity = 0.96,
        shadow = { enabled = true, range = 24, render_power = 3, color = "rgba(00000066)" },
        blur = {
            enabled = true, size = 10, passes = 3,
            vibrancy = 0.25, vibrancy_darkness = 0.2,
            noise = 0.015, contrast = 0.9, brightness = 1.0,
            popups = true, new_optimizations = true,
        },
    },
    animations = { enabled = true },
    dwindle = { preserve_split = true },
    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo = true,
        enable_swallow = true, swallow_regex = "^(kitty|Alacritty)$",
    },
    input = {
        kb_layout = "us",
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = {
            natural_scroll = true,
            tap_to_click = true,
            disable_while_typing = true,
            clickfinger_behavior = true,
        },
    },
})

hl.curve("smooth",  { type = "bezier", points = { {0.22, 1},  {0.36, 1} } })
hl.curve("out",     { type = "bezier", points = { {0.16, 1},  {0.3, 1}  } })
hl.curve("linear",  { type = "bezier", points = { {0, 0},     {1, 1}    } })
hl.curve("spring",  { type = "spring", mass = 1, stiffness = 238.1, damping = 24.2 })

hl.animation({ leaf = "global",        enabled = true, speed = 10,  bezier = "smooth" })
hl.animation({ leaf = "windows",       enabled = true, speed = 4.8, spring = "spring" })
hl.animation({ leaf = "windowsIn",     enabled = true, speed = 4.1, spring = "spring", style = "popin 90%" })
hl.animation({ leaf = "windowsOut",    enabled = true, speed = 2,   bezier = "smooth", style = "popin 90%" })
hl.animation({ leaf = "fade",          enabled = true, speed = 3,   bezier = "smooth" })
hl.animation({ leaf = "border",        enabled = true, speed = 5,   bezier = "smooth" })
hl.animation({ leaf = "layers",        enabled = true, speed = 4,   bezier = "out" })
hl.animation({ leaf = "layersIn",      enabled = true, speed = 4,   bezier = "out", style = "slide" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 2,   bezier = "smooth", style = "fade" })
hl.animation({ leaf = "workspaces",    enabled = true, speed = 3.5, bezier = "out", style = "slide" })

hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

------------------------------
---- LAYER (BLUR) RULES ----
------------------------------
for _, ns in ipairs({ "waybar", "rofi", "swaync.*", "wallpaper-picker", "logout_dialog" }) do
    hl.layer_rule({ name = "blur-" .. ns, match = { namespace = ns }, blur = true, ignore_alpha = 0, xray = false })
end

---------------------
---- KEYBINDINGS ----
---------------------
local M = "SUPER"
hl.bind(M .. " + Return",       hl.dsp.exec_cmd(terminal))
hl.bind(M .. " + D",            hl.dsp.exec_cmd("pkill -x rofi || rofi -show drun"))
hl.bind(M .. " + Tab",          hl.dsp.exec_cmd("pkill -x rofi || rofi -show window"))
hl.bind(M .. " + W",            hl.dsp.exec_cmd(scripts .. "/wallpaper-picker.sh"))
hl.bind(M .. " + V",            hl.dsp.exec_cmd(scripts .. "/clipboard.sh"))
hl.bind(M .. " + period",       hl.dsp.exec_cmd("pkill -x rofi || rofi -show emoji"))
hl.bind(M .. " + equal",        hl.dsp.exec_cmd("pkill -x rofi || rofi -show calc -modi calc -no-show-match -no-sort"))
hl.bind(M .. " + Escape",       hl.dsp.exec_cmd(scripts .. "/powermenu.sh"))
hl.bind(M .. " + B",            hl.dsp.exec_cmd(scripts .. "/powermode.sh menu"))
hl.bind(M .. " + N",            hl.dsp.exec_cmd("swaync-client -t -sw"))
hl.bind(M .. " + SHIFT + R",    hl.dsp.exec_cmd("hyprctl reload"))
hl.bind(M .. " + L",           hl.dsp.exec_cmd("loginctl lock-session"))
hl.bind(M .. " + E",            hl.dsp.exec_cmd(fileManager))
hl.bind(M .. " + Q",            hl.dsp.window.close())
hl.bind(M .. " + F",            hl.dsp.window.fullscreen())
hl.bind(M .. " + Space",        hl.dsp.window.float({ action = "toggle" }))
hl.bind(M .. " + P",            hl.dsp.window.pseudo())
hl.bind(M .. " + J",            hl.dsp.layout("togglesplit"))
hl.bind(M .. " + SHIFT + C",    hl.dsp.exec_cmd("hyprpicker -a"))
hl.bind(M .. " + SHIFT + N",    hl.dsp.exec_cmd("~/.config/waybar/scripts/nightlight.sh next"))

hl.bind("Print",                hl.dsp.exec_cmd(scripts .. "/screenshot.sh region"))
hl.bind("SHIFT + Print",        hl.dsp.exec_cmd(scripts .. "/screenshot.sh screen"))

for _, d in ipairs({ "left", "right", "up", "down" }) do
    hl.bind(M .. " + " .. d,             hl.dsp.focus({ direction = d }))
    hl.bind(M .. " + SHIFT + " .. d,     hl.dsp.window.move({ direction = d }))
end

for i = 1, 10 do
    local key = i % 10
    hl.bind(M .. " + " .. key,           hl.dsp.focus({ workspace = i }))
    hl.bind(M .. " + SHIFT + " .. key,   hl.dsp.window.move({ workspace = i }))
end

hl.bind(M .. " + S",            hl.dsp.workspace.toggle_special("magic"))
hl.bind(M .. " + SHIFT + S",    hl.dsp.window.move({ workspace = "special:magic" }))
hl.bind(M .. " + mouse_down",   hl.dsp.focus({ workspace = "e+1" }))
hl.bind(M .. " + mouse_up",     hl.dsp.focus({ workspace = "e-1" }))
hl.bind(M .. " + mouse:272",    hl.dsp.window.drag(),   { mouse = true })
hl.bind(M .. " + mouse:273",    hl.dsp.window.resize(), { mouse = true })

-- Hardware keys
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })
hl.bind("XF86AudioNext",        hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause",       hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",        hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",        hl.dsp.exec_cmd("playerctl previous"),   { locked = true })
hl.bind("XF86PowerOff",         hl.dsp.exec_cmd(scripts .. "/powermenu.sh"), { locked = true })

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------
hl.window_rule({ name = "suppress-maximize", match = { class = ".*" }, suppress_event = "maximize" })
hl.window_rule({
    name = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})
for _, cls in ipairs({ "pavucontrol", "blueman-manager", "nm-connection-editor", "hyprpwcenter", "hyprsysteminfo", "org.kde.polkit-kde-authentication-agent-1" }) do
    hl.window_rule({ name = "float-" .. cls, match = { class = cls }, float = true, center = true })
end
